+    /** Exactly one way to identify the guest: CPF, or CNPJ with company name, or passport with country. */
+    private static Identification readIdentification(CreateReservationRequest body) {
+        boolean cpf = !isBlank(body.guestCpf());
+        boolean anyCompany = !isBlank(body.companyCnpj()) || !isBlank(body.companyName());
+        boolean company = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
+        boolean anyPassport = !isBlank(body.guestPassport()) || !isBlank(body.guestCountry());
+        boolean passport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());
+        if (cpf && !anyCompany && !anyPassport) {
+            return new Identification.Cpf(body.guestCpf());
+        }
+        if (company && !cpf && !anyPassport) {
+            return new Identification.Company(body.companyCnpj(), body.companyName());
+        }
+        if (passport && !cpf && !anyCompany) {
+            return new Identification.Passport(body.guestPassport(), body.guestCountry());
+        }
+        throw new HotelException(
+                ErrorCode.INVALID_REQUEST,
+                "identify the guest with guestCpf, or companyCnpj and companyName, or guestPassport and guestCountry");
+    }
